-- Read-only quarterly score. Execute this SELECT independently.
WITH sizes AS (SELECT 3600 block_s,'1h' block_type,12 expected_slots UNION ALL SELECT 21600,'6h',72 UNION ALL SELECT 86400,'24h',288), candidates AS (SELECT s.block_s,s.block_type,s.expected_slots,FLOOR((a.dateTime-1585699200)/s.block_s)*s.block_s+1585699200 block_start,COUNT(*) target_n,MIN(a.dateTime) first_t,MAX(a.dateTime) last_t FROM sizes s JOIN loucka_reconstruction.archive a ON a.dateTime>=1585699200 AND a.dateTime<1593561600 AND a.outTemp IS NOT NULL AND a.interval=5 AND NOT EXISTS (SELECT 1 FROM loucka_reconstruction.reconstruction_changes c WHERE c.target_time=a.dateTime AND c.variable='outTemp') GROUP BY s.block_s,s.block_type,s.expected_slots,block_start HAVING target_n=s.expected_slots AND first_t=block_start AND last_t=block_start+s.block_s-300 AND block_start+s.block_s<1593561600), blocks AS (SELECT c.*,l.outTemp left_y,r.outTemp right_y FROM candidates c JOIN loucka_reconstruction.archive l ON l.dateTime=c.block_start-300 AND l.outTemp IS NOT NULL AND l.interval=5 AND NOT EXISTS (SELECT 1 FROM loucka_reconstruction.reconstruction_changes x WHERE x.target_time=l.dateTime AND x.variable='outTemp') JOIN loucka_reconstruction.archive r ON r.dateTime=c.block_start+c.block_s AND r.outTemp IS NOT NULL AND r.interval=5 AND NOT EXISTS (SELECT 1 FROM loucka_reconstruction.reconstruction_changes x WHERE x.target_time=r.dateTime AND x.variable='outTemp')), scores AS (SELECT b.block_type,b.block_start,t.dateTime,t.outTemp y,b.left_y+(b.right_y-b.left_y)*(t.dateTime-(b.block_start-300))/(b.block_s+300) interp,r.temperature_c ref,CASE WHEN r.temperature_c IS NOT NULL AND r.source_resolution='5min' AND r.quality_status='reference_only' THEN 1 ELSE 0 END ref_ok,CASE WHEN r.temperature_c=0 AND t.outTemp>=20 THEN 1 ELSE 0 END zero_hot,(0.7886750170162296+0.9352562666974354*r.temperature_c+-0.20129399741209056*SIN(2*PI()*MOD(t.dateTime,86400)/86400)+-0.09305546547425936*COS(2*PI()*MOD(t.dateTime,86400)/86400)+-0.3075224035244028*SIN(2*PI()*(CASE WHEN t.dateTime<1577836800 THEN t.dateTime-1546300800 ELSE t.dateTime-1577836800 END)/(CASE WHEN t.dateTime>=1577836800 THEN 31622400 ELSE 31536000 END))+-1.496803043901965*COS(2*PI()*(CASE WHEN t.dateTime<1577836800 THEN t.dateTime-1546300800 ELSE t.dateTime-1577836800 END)/(CASE WHEN t.dateTime>=1577836800 THEN 31622400 ELSE 31536000 END))) ols FROM blocks b JOIN loucka_reconstruction.archive t ON t.dateTime>=b.block_start AND t.dateTime<b.block_start+b.block_s AND t.outTemp IS NOT NULL AND t.interval=5 AND NOT EXISTS (SELECT 1 FROM loucka_reconstruction.reconstruction_changes x WHERE x.target_time=t.dateTime AND x.variable='outTemp') LEFT JOIN loucka_reconstruction.reference_observations r ON r.station_id='luhamet_sehradice' AND r.observed_at_utc=t.dateTime), agg AS (SELECT block_type,block_start,COUNT(*) point_n,SUM(ref_ok) ref_n,SUM(CASE WHEN ref_ok=1 THEN zero_hot ELSE 0 END) zero_hot_n,SUM(ABS(interp-y)) interp_abs_all,SUM(POW(interp-y,2)) interp_sq_all,SUM(interp-y) interp_err_all,SUM(CASE WHEN ref_ok=1 THEN ABS(interp-y) ELSE 0 END) interp_abs_pair,SUM(CASE WHEN ref_ok=1 THEN POW(interp-y,2) ELSE 0 END) interp_sq_pair,SUM(CASE WHEN ref_ok=1 THEN interp-y ELSE 0 END) interp_err_pair,SUM(CASE WHEN ref_ok=1 THEN ABS(ref-y) ELSE 0 END) direct_abs,SUM(CASE WHEN ref_ok=1 THEN POW(ref-y,2) ELSE 0 END) direct_sq,SUM(CASE WHEN ref_ok=1 THEN ref-y ELSE 0 END) direct_err,SUM(CASE WHEN ref_ok=1 THEN ABS(ols-y) ELSE 0 END) ols_abs,SUM(CASE WHEN ref_ok=1 THEN POW(ols-y,2) ELSE 0 END) ols_sq,SUM(CASE WHEN ref_ok=1 THEN ols-y ELSE 0 END) ols_err,SUM(CASE WHEN ref_ok=1 AND zero_hot=0 THEN ABS(interp-y) ELSE 0 END) interp_abs_nonflag,SUM(CASE WHEN ref_ok=1 AND zero_hot=0 THEN POW(interp-y,2) ELSE 0 END) interp_sq_nonflag,SUM(CASE WHEN ref_ok=1 AND zero_hot=0 THEN ABS(ref-y) ELSE 0 END) direct_abs_nonflag,SUM(CASE WHEN ref_ok=1 AND zero_hot=0 THEN POW(ref-y,2) ELSE 0 END) direct_sq_nonflag,SUM(CASE WHEN ref_ok=1 AND zero_hot=0 THEN ABS(ols-y) ELSE 0 END) ols_abs_nonflag,SUM(CASE WHEN ref_ok=1 AND zero_hot=0 THEN POW(ols-y,2) ELSE 0 END) ols_sq_nonflag,SUM(CASE WHEN ref_ok=1 AND zero_hot=0 AND y<=0 THEN 1 ELSE 0 END) freeze_n,SUM(CASE WHEN ref_ok=1 AND zero_hot=0 AND y<=0 THEN ABS(interp-y) ELSE 0 END) interp_abs_freeze,SUM(CASE WHEN ref_ok=1 AND zero_hot=0 AND y<=0 THEN POW(interp-y,2) ELSE 0 END) interp_sq_freeze,SUM(CASE WHEN ref_ok=1 AND zero_hot=0 AND y<=0 THEN ABS(ref-y) ELSE 0 END) direct_abs_freeze,SUM(CASE WHEN ref_ok=1 AND zero_hot=0 AND y<=0 THEN POW(ref-y,2) ELSE 0 END) direct_sq_freeze,SUM(CASE WHEN ref_ok=1 AND zero_hot=0 AND y<=0 THEN ABS(ols-y) ELSE 0 END) ols_abs_freeze,SUM(CASE WHEN ref_ok=1 AND zero_hot=0 AND y<=0 THEN POW(ols-y,2) ELSE 0 END) ols_sq_freeze FROM scores GROUP BY block_type,block_start) SELECT '2020Q2' AS period,block_type,COUNT(*) complete_blocks,SUM(point_n) target_n,SUM(ref_n) reference_n,SUM(zero_hot_n) zero_hot_n,SUM(interp_abs_all) interp_abs_all,SUM(interp_sq_all) interp_sq_all,SUM(interp_err_all) interp_err_all,SUM(interp_abs_pair) interp_abs_pair,SUM(interp_sq_pair) interp_sq_pair,SUM(interp_err_pair) interp_err_pair,SUM(direct_abs) direct_abs,SUM(direct_sq) direct_sq,SUM(direct_err) direct_err,SUM(ols_abs) ols_abs,SUM(ols_sq) ols_sq,SUM(ols_err) ols_err,SUM(interp_abs_nonflag) interp_abs_nonflag,SUM(interp_sq_nonflag) interp_sq_nonflag,SUM(direct_abs_nonflag) direct_abs_nonflag,SUM(direct_sq_nonflag) direct_sq_nonflag,SUM(ols_abs_nonflag) ols_abs_nonflag,SUM(ols_sq_nonflag) ols_sq_nonflag,SUM(freeze_n) freeze_n,SUM(interp_abs_freeze) interp_abs_freeze,SUM(interp_sq_freeze) interp_sq_freeze,SUM(direct_abs_freeze) direct_abs_freeze,SUM(direct_sq_freeze) direct_sq_freeze,SUM(ols_abs_freeze) ols_abs_freeze,SUM(ols_sq_freeze) ols_sq_freeze FROM agg GROUP BY block_type ORDER BY block_type;

-- Read-only aggregate absolute-error histogram for point quantiles. Execute independently.
WITH sizes AS (SELECT 3600 block_s,'1h' block_type,12 expected_slots UNION ALL SELECT 21600,'6h',72 UNION ALL SELECT 86400,'24h',288), candidates AS (SELECT s.block_s,s.block_type,s.expected_slots,FLOOR((a.dateTime-1585699200)/s.block_s)*s.block_s+1585699200 block_start,COUNT(*) target_n,MIN(a.dateTime) first_t,MAX(a.dateTime) last_t FROM sizes s JOIN loucka_reconstruction.archive a ON a.dateTime>=1585699200 AND a.dateTime<1593561600 AND a.outTemp IS NOT NULL AND a.interval=5 AND NOT EXISTS (SELECT 1 FROM loucka_reconstruction.reconstruction_changes c WHERE c.target_time=a.dateTime AND c.variable='outTemp') GROUP BY s.block_s,s.block_type,s.expected_slots,block_start HAVING target_n=s.expected_slots AND first_t=block_start AND last_t=block_start+s.block_s-300 AND block_start+s.block_s<1593561600), blocks AS (SELECT c.*,l.outTemp left_y,r.outTemp right_y FROM candidates c JOIN loucka_reconstruction.archive l ON l.dateTime=c.block_start-300 AND l.outTemp IS NOT NULL AND l.interval=5 AND NOT EXISTS (SELECT 1 FROM loucka_reconstruction.reconstruction_changes x WHERE x.target_time=l.dateTime AND x.variable='outTemp') JOIN loucka_reconstruction.archive r ON r.dateTime=c.block_start+c.block_s AND r.outTemp IS NOT NULL AND r.interval=5 AND NOT EXISTS (SELECT 1 FROM loucka_reconstruction.reconstruction_changes x WHERE x.target_time=r.dateTime AND x.variable='outTemp')), scores AS (SELECT b.block_type,b.block_start,t.dateTime,t.outTemp y,b.left_y+(b.right_y-b.left_y)*(t.dateTime-(b.block_start-300))/(b.block_s+300) interp,r.temperature_c ref,CASE WHEN r.temperature_c IS NOT NULL AND r.source_resolution='5min' AND r.quality_status='reference_only' THEN 1 ELSE 0 END ref_ok,CASE WHEN r.temperature_c=0 AND t.outTemp>=20 THEN 1 ELSE 0 END zero_hot,(0.7886750170162296+0.9352562666974354*r.temperature_c+-0.20129399741209056*SIN(2*PI()*MOD(t.dateTime,86400)/86400)+-0.09305546547425936*COS(2*PI()*MOD(t.dateTime,86400)/86400)+-0.3075224035244028*SIN(2*PI()*(CASE WHEN t.dateTime<1577836800 THEN t.dateTime-1546300800 ELSE t.dateTime-1577836800 END)/(CASE WHEN t.dateTime>=1577836800 THEN 31622400 ELSE 31536000 END))+-1.496803043901965*COS(2*PI()*(CASE WHEN t.dateTime<1577836800 THEN t.dateTime-1546300800 ELSE t.dateTime-1577836800 END)/(CASE WHEN t.dateTime>=1577836800 THEN 31622400 ELSE 31536000 END))) ols FROM blocks b JOIN loucka_reconstruction.archive t ON t.dateTime>=b.block_start AND t.dateTime<b.block_start+b.block_s AND t.outTemp IS NOT NULL AND t.interval=5 AND NOT EXISTS (SELECT 1 FROM loucka_reconstruction.reconstruction_changes x WHERE x.target_time=t.dateTime AND x.variable='outTemp') LEFT JOIN loucka_reconstruction.reference_observations r ON r.station_id='luhamet_sehradice' AND r.observed_at_utc=t.dateTime), errors AS (SELECT '2020Q2' period,block_type,'all' AS grp,'interpolation' AS method,FLOOR(ABS(interp-y)*10) AS error_decic_bucket FROM scores WHERE ref_ok=1 UNION ALL SELECT '2020Q2' period,block_type,'all' AS grp,'direct' AS method,FLOOR(ABS(ref-y)*10) AS error_decic_bucket FROM scores WHERE ref_ok=1 UNION ALL SELECT '2020Q2' period,block_type,'all' AS grp,'harmonic_ols' AS method,FLOOR(ABS(ols-y)*10) AS error_decic_bucket FROM scores WHERE ref_ok=1 UNION ALL SELECT '2020Q2' period,block_type,'nonflag' AS grp,'interpolation' AS method,FLOOR(ABS(interp-y)*10) AS error_decic_bucket FROM scores WHERE ref_ok=1 AND zero_hot=0 UNION ALL SELECT '2020Q2' period,block_type,'nonflag' AS grp,'direct' AS method,FLOOR(ABS(ref-y)*10) AS error_decic_bucket FROM scores WHERE ref_ok=1 AND zero_hot=0 UNION ALL SELECT '2020Q2' period,block_type,'nonflag' AS grp,'harmonic_ols' AS method,FLOOR(ABS(ols-y)*10) AS error_decic_bucket FROM scores WHERE ref_ok=1 AND zero_hot=0 UNION ALL SELECT '2020Q2' period,block_type,'freeze_nonflag' AS grp,'interpolation' AS method,FLOOR(ABS(interp-y)*10) AS error_decic_bucket FROM scores WHERE ref_ok=1 AND zero_hot=0 AND y<=0 UNION ALL SELECT '2020Q2' period,block_type,'freeze_nonflag' AS grp,'direct' AS method,FLOOR(ABS(ref-y)*10) AS error_decic_bucket FROM scores WHERE ref_ok=1 AND zero_hot=0 AND y<=0 UNION ALL SELECT '2020Q2' period,block_type,'freeze_nonflag' AS grp,'harmonic_ols' AS method,FLOOR(ABS(ols-y)*10) AS error_decic_bucket FROM scores WHERE ref_ok=1 AND zero_hot=0 AND y<=0) SELECT period,block_type,grp,method,error_decic_bucket,COUNT(*) AS n FROM errors GROUP BY period,block_type,grp,method,error_decic_bucket ORDER BY block_type,grp,method,error_decic_bucket;
